#include "../Source/Processor.h"
#include <cmath>
#include <cstdlib>
#include <iostream>
#include <memory>
void check(bool ok,const char* message){if(!ok){std::cerr<<message<<'\n';std::exit(1);}}void set(Processor& p,const char* id,float value){auto* parameter=p.state.getParameter(id);check(parameter,"missing parameter");parameter->setValueNotifyingHost(parameter->convertTo0to1(value));}
int main(){for(double rate:{44100.,48000.,96000.,192000.}){auto legacy=std::make_unique<Processor>(),strong=std::make_unique<Processor>();for(auto* p:{legacy.get(),strong.get()}){set(*p,"eqPresent",0);set(*p,"limPresent",0);set(*p,"dynamicsPresent",1);set(*p,"dynamicsOn",1);set(*p,"dynThreshold",-30);set(*p,"dynRatio",6);set(*p,"dynAttack",5);p->setRateAndBufferSizeDetails(rate,257);p->prepareToPlay(rate,257);check(p->getLatencySamples()==static_cast<int>(std::ceil(rate*.005))+masterlab::AnalogExciter::latencySamples()+masterlab::FinalTruePeak::latencySamples,"Dynamics controls changed PDC");}set(*strong,"dynamicsIntensity",2);set(*strong,"dynPunch",70);juce::AudioBuffer<float> a(2,257),b(2,257);juce::MidiBuffer midi;double ea=0,eb=0;for(int block=0;block<400;++block){for(int i=0;i<257;++i){const double t=(block*257+i)/rate;const float envelope=(block%20==0&&i<8)?2.f:1.f;a.setSample(0,i,envelope*.35f*std::sin(6.283185307179586*701*t));a.setSample(1,i,envelope*.3f*std::sin(6.283185307179586*701*t+.1));}b.makeCopyOf(a);legacy->processBlock(a,midi);strong->processBlock(b,midi);if(block>200)for(int c=0;c<2;++c)for(int i=0;i<257;++i){ea+=a.getSample(c,i)*a.getSample(c,i);eb+=b.getSample(c,i)*b.getSample(c,i);}}check(std::abs(10*std::log10(eb/ea))>.5,"APVTS intensity/Punch does not reach DSP output");juce::MemoryBlock state;strong->getStateInformation(state);Processor restored;restored.setStateInformation(state.getData(),static_cast<int>(state.getSize()));for(const char* id:{"dynamicsIntensity","dynPunch","dynDelta"})check(restored.state.getRawParameterValue(id)->load()==strong->state.getRawParameterValue(id)->load(),"Phase 2B state did not restore");}std::cout<<"Passed: Phase 2B APVTS, output, state and PDC at four rates\n";}
